<?php

require_once $_SERVER['DOCUMENT_ROOT']."/chat/bbcode.php";

// ignore newlines
$bbcode->SetIgnoreNewlines(true);

// text parsing functions
function parseCondensedTqs($str) {
	// autogenerated alt text
	$str = preg_replace("/\%\%([^\%]*)\%/","<u class='tq'>$1</u>",$str);
	$str = preg_replace("/\%N\%([^\%]*)\%/","<u class='tq-nep'>$1</u>",$str);
	// with alt text
	$str = preg_replace("/\%A\%([^\%]*)\\\\([^\%]*)\%/","<u class='tq' data-a=\"$1\">$2</u>",$str);
	// emoticons
	$str = preg_replace("/\%E\%([^\%]*)\\\\([^\%]*)\%/","<u class='tq-e' data-a=\"$1\">$2</u>",$str);
	$str = preg_replace("/\%E\%([^\%]*)\%/","<u class='tq-e'>$1</u>",$str);
	return $str;
}
function parseLocalSources($str) {
	global $basePath; global $table;
	$str = preg_replace("/src=\"([^\/][^https:])/","src=\"/blog-data/$table/$1",$str);
	$str = preg_replace("/href=\"([^\/])/","href=\"$basePath/$1",$str);
	return $str;
}
function parsePostText($str) {
	return getPolishedBbcode(parseLocalSources(parseCondensedTqs($str)));
}

?>